// LoadingAnimation.jsx
import React, { useState, useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import './LoadingAnimation.css';

const LoadingAnimation = ({ onLoadingComplete }) => {
  const [isVisible, setIsVisible] = useState(true);
  const overlayRef = useRef(null);
  const mandalaRef = useRef(null);
  const nameRef = useRef(null);
  const sloganRef = useRef(null);
  const blessingRef = useRef(null);
  const diyaRef = useRef(null);
  const particlesRef = useRef([]);

  useEffect(() => {
    const tl = gsap.timeline();

    // Create particles
    const particleCount = 50;
    for (let i = 0; i < particleCount; i++) {
      const particle = document.createElement('div');
      particle.className = 'particle';
      particle.style.left = `${Math.random() * 100}%`;
      particle.style.top = `${Math.random() * 100}%`;
      overlayRef.current.appendChild(particle);
      particlesRef.current.push(particle);
    }

    // Animate particles floating
    particlesRef.current.forEach((particle, i) => {
      gsap.to(particle, {
        y: `${Math.random() * 100 - 50}px`,
        x: `${Math.random() * 100 - 50}px`,
        opacity: Math.random() * 0.5 + 0.3,
        duration: Math.random() * 3 + 2,
        repeat: -1,
        yoyo: true,
        ease: 'sine.inOut',
        delay: Math.random() * 2
      });
    });

    // Main animation sequence
    tl.to(mandalaRef.current, {
      opacity: 1,
      scale: 1,
      duration: 1.5,
      ease: 'power2.out'
    })
    .to('.mandala-layer', {
      rotation: 360,
      duration: 20,
      repeat: -1,
      ease: 'none',
      stagger: {
        each: 0.2,
        from: 'start'
      }
    }, 0)
    .to(diyaRef.current, {
      opacity: 1,
      y: -20,
      duration: 1.2,
      ease: 'power3.out'
    }, 0.5)
    .to('.flame', {
      scale: 1.1,
      duration: 0.15,
      repeat: -1,
      yoyo: true,
      ease: 'sine.inOut'
    }, 1)
    .fromTo(nameRef.current.children, {
      opacity: 0,
      y: -50,
      rotationX: 90
    }, {
      opacity: 1,
      y: 0,
      rotationX: 0,
      duration: 0.8,
      stagger: 0.08,
      ease: 'back.out(1.7)'
    }, 0.8)
    .fromTo(sloganRef.current, {
      opacity: 0,
      y: 30
    }, {
      opacity: 1,
      y: 0,
      duration: 1,
      ease: 'power2.out'
    }, 2)
    .fromTo(blessingRef.current.children, {
      opacity: 0,
      scale: 0.8
    }, {
      opacity: 1,
      scale: 1,
      duration: 1,
      stagger: 0.2,
      ease: 'elastic.out(1, 0.5)'
    }, 2.5);

    // Light rays animation
    gsap.to('.light-ray', {
      rotation: 360,
      duration: 30,
      repeat: -1,
      ease: 'none'
    });

    // Exit animation
    const exitTimer = setTimeout(() => {
      gsap.to(overlayRef.current, {
        opacity: 0,
        duration: 1,
        ease: 'power2.inOut',
        onComplete: () => {
          setIsVisible(false);
          if (onLoadingComplete) onLoadingComplete();
        }
      });
    }, 5000);

    return () => {
      clearTimeout(exitTimer);
      tl.kill();
    };
  }, [onLoadingComplete]);

  if (!isVisible) return null;

  return (
    <div className="loading-overlay" ref={overlayRef}>
      <div className="gradient-bg"></div>

      {/* Light rays */}
      <div className="light-rays">
        {[...Array(12)].map((_, i) => (
          <div key={i} className="light-ray" style={{ '--ray-index': i }}></div>
        ))}
      </div>

      {/* Geometric Mandala */}
      <div className="mandala-container" ref={mandalaRef}>
        {[...Array(5)].map((_, i) => (
          <div key={i} className="mandala-layer"></div>
        ))}
        <div className="mandala-center"></div>
      </div>

      {/* Premium Diya */}
      <div className="premium-diya" ref={diyaRef}>
        <div className="diya-glow"></div>
        <div className="diya-base">
          <div className="diya-body"></div>
          <div className="diya-wick"></div>
        </div>
        <div className="flame"></div>
      </div>

      {/* Content */}
      <div className="content-wrapper">
        <div className="name-container" ref={nameRef}>
          {['R', 'o', 'b', 'i', 'n', ' ', 'T', 's', 'a', 'i'].map((letter, i) => (
            <span key={i} className="name-letter">{letter}</span>
          ))}
        </div>

        <div className="slogan" ref={sloganRef}>
          Diagnosing your property goals, prescribing the right solutions
        </div>

        <div className="blessing-container" ref={blessingRef}>
          <div className="hindi-text">शुभ दीपावली</div>
          <div className="english-text">Happy Deepavali</div>
        </div>
      </div>

      {/* Corner ornaments */}
      <div className="corner-ornament top-left"></div>
      <div className="corner-ornament top-right"></div>
      <div className="corner-ornament bottom-left"></div>
      <div className="corner-ornament bottom-right"></div>
    </div>
  );
};

export default LoadingAnimation;
